CREATE TABLE IF NOT EXISTS library_lm_xv_kdp_pages_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL REFERENCES library_documents(id),source_run_id TEXT NOT NULL,pdf_page INTEGER NOT NULL,printed_page INTEGER,page_status TEXT NOT NULL,raw_text TEXT NOT NULL,normalized_text TEXT NOT NULL,text_hash TEXT NOT NULL,extraction_engine TEXT NOT NULL,extraction_quality_score NUMERIC NOT NULL,has_hebrew BOOLEAN NOT NULL,has_latin BOOLEAN NOT NULL,block_count INTEGER NOT NULL,reading_order_method TEXT NOT NULL,column_count_estimate INTEGER NOT NULL,layout_assist_used BOOLEAN NOT NULL DEFAULT false,needs_layout_review BOOLEAN NOT NULL DEFAULT false,warnings JSONB NOT NULL DEFAULT '[]'::jsonb,UNIQUE(source_run_id,pdf_page));
CREATE TABLE IF NOT EXISTS library_lm_xv_kdp_page_blocks_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL REFERENCES library_documents(id),source_run_id TEXT NOT NULL,pdf_page INTEGER NOT NULL,block_index_original INTEGER NOT NULL,block_index_ordered INTEGER NOT NULL,reading_order_method TEXT NOT NULL,bbox JSONB NOT NULL,text TEXT NOT NULL,normalized_text TEXT NOT NULL,text_hash TEXT NOT NULL,block_role_candidate TEXT NOT NULL,script_mix JSONB NOT NULL,confidence NUMERIC NOT NULL,warnings JSONB NOT NULL DEFAULT '[]'::jsonb,UNIQUE(source_run_id,pdf_page,block_index_original));
CREATE INDEX IF NOT EXISTS idx_lm_xv_pages_run_page ON library_lm_xv_kdp_pages_v1(source_run_id,pdf_page);
CREATE INDEX IF NOT EXISTS idx_lm_xv_blocks_page ON library_lm_xv_kdp_page_blocks_v1(source_run_id,pdf_page);
CREATE OR REPLACE VIEW library_lm_xv_kdp_page_first_v1 AS SELECT * FROM library_lm_xv_kdp_pages_v1;
CREATE OR REPLACE VIEW library_lm_xv_kdp_blocks_v1 AS SELECT * FROM library_lm_xv_kdp_page_blocks_v1;
CREATE OR REPLACE VIEW library_lm_xv_kdp_search_ready_v1 AS SELECT p.document_id,d.document_code,d.title,p.source_run_id,p.pdf_page,p.printed_page,p.page_status,p.raw_text,p.normalized_text,p.text_hash,p.block_count,p.reading_order_method,p.column_count_estimate,p.has_hebrew,p.has_latin,p.layout_assist_used,p.needs_layout_review,coalesce(jsonb_agg(distinct b.block_role_candidate) filter(where b.id is not null),'[]'::jsonb) block_role_candidates,p.warnings FROM library_lm_xv_kdp_pages_v1 p JOIN library_documents d ON d.id=p.document_id LEFT JOIN library_lm_xv_kdp_page_blocks_v1 b ON b.source_run_id=p.source_run_id AND b.pdf_page=p.pdf_page GROUP BY p.id,d.document_code,d.title;
